(
    'gomateshwara',
    'Gomateshwara Monolith (Shravanabelagola)',
    'गोमटेश्वर बाहुबली (श्रवणबेलगोला)',
    ARRAY['Sravana Belgola', 'Vindhyagiri Bahubali', 'Gommata', 'Dakkina Kashi']::text[],
    'historical_site',
    'Digambara',
    'Karnataka',
    'Hassan',
    'Shravanabelagola',
    '573135',
    'Gomateshwara Monolith (Shravanabelagola), Shravanabelagola, District Hassan, Karnataka - 573135',
    12.8586,
    76.4861,
    'https://www.google.com/maps/search/?api=1&query=12.8586,76.4861',
    'Gomateshwara Monolith (Shravanabelagola) is an auspicious Digambar Jain pilgrimage destination situated in Shravanabelagola, Karnataka. Renowned for its monumental 57-foot free-standing monolithic granite sculpture of Lord Bahubali sculpted atop Vindhyagiri hill in 981 CE by General Chavundaraya of the Western Ganga dynasty. Internationally recognized as the sanctuary of spiritual devotion and monumental architectural legacy of classical Digambar Jainism.',
    'Shravanabelagola became the central fountainhead of Digambar monastic life in peninsular India following the historic southward migration of Acharya Bhadrabahu and the Maurya emperor Chandragupta in the 3rd century BCE. Across successive epochs, the twin hills of Vindhyagiri and Chandragiri developed into a monumental open-air museum of architecture, housing over 500 cataloged epigraphs spanning from archaic Ganga grants to Vijayanagara royal decrees.',
    'Supreme Digambar Atishaya and Siddha Kshetra. Site of the celebrated Mahamastakabhisheka festival observed once every 12 years.',
    'Bhagwan Bahubali Gomateshwara, in contemplative Khadgasana (Standing) posture, measuring approximately 57 feet (17.37 meters), sculpted from Grey Granite (Monolithic Single Tor), dating to the 981 CE, (Kayotsarga ascetic stance; serpent anthills and Madhavi creepers carved along thighs and arms; foot pedestal inscribed in Old Kannada, Tamil-Grantha, and archaic Marathi.).',
    '{"morning":"06:00 - 12:30 PM (Morning Abhishek, Pakhsal & Jin Puja)","evening":"05:00 PM - 18:30 (Hill gates) (Sandhya Darshan & Deep Aradhana)","notes":"Temple opens early for morning pakhsal; visitors are requested to wear traditional clean clothes."}'::jsonb,
    ARRAY['Digambar Dharamshala', 'Shuddh Jain Bhojanshala', 'Drinking Water', 'Pilgrim Rest Hall', 'Vehicle Parking']::text[],
    'Hillside or elevated terrain with stone-carved steps; doli/chair palanquin assistance is generally available for elderly devotees.',
    '{"railway":"Shravanabelagola Railway Station (connected to major junction via North Central / Western / South Western Railways)","airport":"Kempegowda International Airport, Bengaluru (BLR) - 150 km / Mysuru Airport (MYQ)","road":"Connected via State & National Highway network; local bus and taxi services available from Shravanabelagola"}'::jsonb,
    'Inquire at Local Digambar Jain Prabandhakarini Committee Office',
    'https://realjainism.bot.cd/tirths/gomateshwara',
    'https://rllagzfmqpkzjhxnzxpf.supabase.co/storage/v1/object/public/tirth-photos/Gomateshwara%20Monolith%20(Shravanabelagola).png',
    'published'
),
(
    'deogarh',
    'Deogarh Fort Jain Temple Complex',
    'देवगढ़ किला दिगम्बर जैन मंदिर समूह',
    ARRAY['Luachchhagiri', 'Devagadh', 'Kirtigiri Durg']::text[],
    'temple_complex',
    'Digambara',
    'Uttar Pradesh',
    'Lalitpur',
    'Deogarh',
    '284403',
    'Deogarh Fort Jain Temple Complex, Deogarh, District Lalitpur, Uttar Pradesh - 284403',
    24.5264,
    78.2514,
    'https://www.google.com/maps/search/?api=1&query=24.5264,78.2514',
    'Deogarh Fort Jain Temple Complex is an auspicious Digambar Jain pilgrimage destination situated in Deogarh, Uttar Pradesh. A fortified medieval ensemble of 31 Digambar Jain temples nestled within the ancient hill fort on the cliffs of the Betwa River. Contains one of India''s richest epigraphical and iconographical repositories of the Gurjara-Pratihara and Chandela periods.',
    'Deogarh (historically named Luachchhagiri) was a fortified trade and monastic emporium. During the 9th to 12th centuries under the Gurjara-Pratihara monarchs Mihira Bhoja and Mahendrapala, the Saraswati Gaccha established an influential scriptorium and sculptor guild here, producing over 2,000 carved stone panels and 400 monolithic statues.',
    'Crucial historical Atishaya Kshetra housing intact classical Pratihara and post-Gupta Digambar iconography.',
    'Bhagwan Shantinatha, in contemplative Khadgasana (Standing) posture, measuring approximately 12.5 feet, sculpted from Red Sandstone, dating to the 9th Century CE, (Flanked by yaksha-yakshi attendants and celestial vidyadharas.).',
    '{"morning":"06:00 - 12:30 PM (Morning Abhishek, Pakhsal & Jin Puja)","evening":"05:00 PM - 17:30 (Sandhya Darshan & Deep Aradhana)","notes":"Temple opens early for morning pakhsal; visitors are requested to wear traditional clean clothes."}'::jsonb,
    ARRAY['Digambar Dharamshala', 'Shuddh Jain Bhojanshala', 'Drinking Water', 'Pilgrim Rest Hall', 'Vehicle Parking']::text[],
    'Paved courtyard offering convenient ground-level pedestrian access throughout the temple complex.',
    '{"railway":"Deogarh Railway Station (connected to major junction via North Central / Western / South Western Railways)","airport":"Gwalior Airport (GWL) - 140 km / Raja Bhoj Airport, Bhopal (BHO) - 220 km","road":"Connected via State & National Highway network; local bus and taxi services available from Deogarh"}'::jsonb,
    'Inquire at Local Digambar Jain Prabandhakarini Committee Office',
