    'published'
),
(
    'khajuraho-jain',
    'Khajuraho Eastern Jain Enclosure',
    'खजुराहो पूर्वी दिगम्बर जैन मंदिर समूह',
    ARRAY['Jinanatha Temples of Khajuraho', 'Kharjuravahaka']::text[],
