    24.8488,
    79.9288,
    'https://www.google.com/maps/search/?api=1&query=24.8488,79.9288',
    'Khajuraho Eastern Jain Enclosure is an auspicious Digambar Jain pilgrimage destination situated in Khajuraho, Madhya Pradesh. A cluster of monumental sandstone temples in the eastern group of Khajuraho built between the 10th and 12th centuries under Chandela royal patronage. The Parshvanatha and Adinatha temples are pinnacles of classical Indian nagara architectural expression.',
    'The merchant-patron Pahila, held in deep reverence by Chandela King Dhanga, built the majestic Parshvanatha temple in the mid-10th century. Khajuraho flourished as an ecumenical capital where Digambar Jain monastic foundations received imperial tax exemptions and royal grants.',
    'UNESCO World Heritage Site and historically documented Digambar cultural center.',
    'Bhagwan Parshvanatha & Adinatha, in contemplative Padmasana (Seated) posture, sculpted from Buff Sandstone, dating to the 10th Century CE, (Exquisite multi-tiered snake hood canopy over Parshvanatha.).',
    '{"morning":"06:00 - 12:30 PM (Morning Abhishek, Pakhsal & Jin Puja)","evening":"05:00 PM - 18:00 (Sandhya Darshan & Deep Aradhana)","notes":"Temple opens early for morning pakhsal; visitors are requested to wear traditional clean clothes."}'::jsonb,
    ARRAY['Digambar Dharamshala', 'Shuddh Jain Bhojanshala', 'Drinking Water', 'Pilgrim Rest Hall', 'Vehicle Parking']::text[],
    'Paved courtyard offering convenient ground-level pedestrian access throughout the temple complex.',
