(
    'moodabidri',
    'Moodabidri Saavira Kambada Basadi (Thousand Pillar)',
    'मूडबिद्री साविर कम्बाद बसदी (हज़ार खंभा मंदिर)',
    ARRAY['Tribhuvana Tilaka Chudamani', 'Bedra Chandranatha Basadi', 'Jain Kashi of the South']::text[],
    'temple_complex',
    'Digambara',
    'Karnataka',
    'Dakshina Kannada',
    'Moodabidri',
    '574227',
    'Moodabidri Saavira Kambada Basadi (Thousand Pillar), Moodabidri, District Dakshina Kannada, Karnataka - 574227',
    13.0722,
    74.9961,
    'https://www.google.com/maps/search/?api=1&query=13.0722,74.9961',
    'Moodabidri Saavira Kambada Basadi (Thousand Pillar) is an auspicious Digambar Jain pilgrimage destination situated in Moodabidri, Karnataka. Renowned as the ''Jain Kashi of the South'', this monumental 15th-century Digambar basadi features three tiers of sloping granite-slab roofs supported by a forest of 1,000 uniquely carved monolithic granite pillars. Custodian of the irreplaceable sacred 9th-century Dhavala and Jayadhavala palm-leaf manuscripts.',
    'Moodabidri emerged as the spiritual sanctuary of Digambar scholarship in the 14th and 15th centuries. When northern manuscript collections were threatened, the complete text of the Shatkhandagama commentary (Dhavala) was safely transported here and preserved under the spiritual guardianship of the Charukeerthi Bhattaraka Swamiji.',
    'Foremost spiritual, architectural, and manuscript heritage center of South Indian Digambar Jainism.',
    'Bhagwan Chandranatha Swamy, in contemplative Khadgasana (Standing) posture, measuring approximately 8 feet (2.4 meters), sculpted from Cast Panchaloha (Bronze/Brass alloy), dating to the 1430 CE, (Enshrined in the inner sanctum of the third tier.).',
    '{"morning":"06:00 - 12:30 PM (Morning Abhishek, Pakhsal & Jin Puja)","evening":"05:00 PM - 19:30 (Sandhya Darshan & Deep Aradhana)","notes":"Temple opens early for morning pakhsal; visitors are requested to wear traditional clean clothes."}'::jsonb,
    ARRAY['Digambar Dharamshala', 'Shuddh Jain Bhojanshala', 'Drinking Water', 'Pilgrim Rest Hall', 'Vehicle Parking']::text[],
    'Paved courtyard offering convenient ground-level pedestrian access throughout the temple complex.',
    '{"railway":"Moodabidri Railway Station (connected to major junction via North Central / Western / South Western Railways)","airport":"Mangaluru International Airport (IXE) - Approx 35-50 km","road":"Connected via State & National Highway network; local bus and taxi services available from Moodabidri"}'::jsonb,
    'Inquire at Local Digambar Jain Prabandhakarini Committee Office',
    'https://realjainism.bot.cd/tirths/moodabidri',
    'https://rllagzfmqpkzjhxnzxpf.supabase.co/storage/v1/object/public/tirth-photos/Moodabidri%20Saavira%20Kambada%20Basadi%20(Thousand%20Pillar).png',
    'published'
),
(
    'kundalpur',
    'Kundalpur Bade Baba Digambar Jain Temples',
    'कुण्डलपुर बड़े बाबा दिगम्बर जैन मंदिर',
    ARRAY['Bade Baba Kundalpur', 'Kundalgiri']::text[],
    'atishay_kshetra',
    'Digambara',
