    '470661',
    'Kundalpur Bade Baba Digambar Jain Temples, Damoh, District Damoh, Madhya Pradesh - 470661',
    23.9849,
    79.72,
    'https://www.google.com/maps/search/?api=1&query=23.9849,79.72',
    'Kundalpur Bade Baba Digambar Jain Temples is an auspicious Digambar Jain pilgrimage destination situated in Damoh, Madhya Pradesh. Celebrated Digambar Atishaya Kshetra in the Vindhya range, renowned for the colossal ancient monolithic seated idol of ''Bade Baba'' (Lord Adinatha/Rishabhanatha) dating to the 6th–8th century CE. The sacred hill houses a constellation of over 60 historical temples around the Vardhaman Sagar lake.',
    'Inscriptions dating to Vikrama Samvat 1757 (1700 CE) during the reign of Bundela King Chhatrasal confirm the continuous restoration and sacred veneration of Bade Baba. In recent decades, a monumental nagara-style stone temple has been constructed over the ancient sanctum.',
    'Foremost Digambar Atishaya Kshetra of Central India.',
    'Bhagwan Adinatha (Bade Baba), in contemplative Padmasana (Seated) posture, measuring approximately 15 feet, sculpted from Red Sandstone, dating to the c. 6th–8th Century CE, (Seated in meditative dhyana mudra upon a lotus pedestal with Gomukha yaksha.).',
    '{"morning":"05:00 - 12:30 PM (Morning Abhishek, Pakhsal & Jin Puja)","evening":"05:00 PM - 20:00 (Sandhya Darshan & Deep Aradhana)","notes":"Temple opens early for morning pakhsal; visitors are requested to wear traditional clean clothes."}'::jsonb,
    ARRAY['Digambar Dharamshala', 'Shuddh Jain Bhojanshala', 'Drinking Water', 'Pilgrim Rest Hall', 'Vehicle Parking']::text[],
    'Paved courtyard offering convenient ground-level pedestrian access throughout the temple complex.',
    '{"railway":"Damoh Railway Station (connected to major junction via North Central / Western / South Western Railways)","airport":"Dumna Airport, Jabalpur (JLR)","road":"Connected via State & National Highway network; local bus and taxi services available from Damoh"}'::jsonb,
