    86.1361,
    'https://www.google.com/maps/search/?api=1&query=23.9628,86.1361',
    'Shri Sammed Shikharji (Parasnath Hill) is an auspicious Digambar Jain pilgrimage destination situated in Giridih (Madhuban), Jharkhand. The supreme Siddha Kshetra of Jainism. Located on the highest mountain peak of the Chota Nagpur plateau (1,365 m), Shikharji is the hallowed site where twenty of the twenty-four Tirthankars, including Lord Parshvanatha, attained supreme Nirvana.',
    'Referred to in classical Prakrit scriptures and Kalpa Sutra as the primordial mountain of liberation. Epigraphs in Madhuban and across the individual mountain tonks date from the 12th century CE onwards, recording restorations funded by the all-India Sangha.',
    'Supreme Siddha Kshetra of the Jain universe.',
    'Bhagwan Parshvanatha (Parasnath Tonk), in contemplative Kayotsarga posture, sculpted from White Marble & Black Stone Paduka, dating to the Ancient, (Sacred Charan Paduka sheltered by seven-headed serpent canopy.).',
    '{"morning":"04:00 - 12:30 PM (Morning Abhishek, Pakhsal & Jin Puja)","evening":"05:00 PM - 18:00 (Sandhya Darshan & Deep Aradhana)","notes":"Temple opens early for morning pakhsal; visitors are requested to wear traditional clean clothes."}'::jsonb,
