    '{"railway":"Giridih (Madhuban) Railway Station (connected to major junction via North Central / Western / South Western Railways)","airport":"Deoghar International Airport (DGH) - 105 km / Birsa Munda Airport, Ranchi (IXR) - 150 km","road":"Connected via State & National Highway network; local bus and taxi services available from Giridih (Madhuban)"}'::jsonb,
