    'https://www.google.com/maps/search/?api=1&query=25.7182,78.3763',
    'Sonagiri Sacred Hilltop Temples Complex is an auspicious Digambar Jain pilgrimage destination situated in Datia, Madhya Pradesh. A celebrated Digambar Siddha and Atishaya Kshetra where, according to sacred tradition, five and a half crore Munis attained Nirvana alongside ascetic Nang-Anang Kumar. Features 77 white shikhara temples cascading across the granite hill and 26 temples in the village valley below.',
    'Inscriptions dating to the 12th century confirm the ancient status of Sonagiri as an organized Bhattaraka center of the Mula Sangha Kundakundanvaya. Temple 57 houses an 11-foot seated sandstone image of Chandraprabhu bearing an inscription from 1108 CE.',
    'Major Digambar Siddha Kshetra of Central India.',
    'Bhagwan Chandraprabhu (Temple 57), in contemplative Padmasana (Seated) posture, measuring approximately 11 feet, sculpted from Buff Sandstone (White Polished), dating to the 1108 CE, (Crescent moon emblem carved on pedestal; flanked by two 4-foot standing tirthankar images.).',
    '{"morning":"05:30 - 12:30 PM (Morning Abhishek, Pakhsal & Jin Puja)","evening":"05:00 PM - 20:30 (Sandhya Darshan & Deep Aradhana)","notes":"Temple opens early for morning pakhsal; visitors are requested to wear traditional clean clothes."}'::jsonb,
