    'https://www.google.com/maps/search/?api=1&query=25.0911,85.5386',
    'Pawapuri Jal Mandir & Samosharan is an auspicious Digambar Jain pilgrimage destination situated in Pawapuri, Bihar. The supreme Nirvana site where Lord Mahavira, the 24th and last Tirthankar of the current Avasarpini era, attained Moksha in 527 BCE. The Jal Mandir is an ethereal white marble temple erected in the center of an expansive lotus pond (surrounded by water lilies), marking the spot of Lord Mahavira''s holy cremation.',
    'Following Lord Mahavira''s Nirvana on Kartika Krishna Amavasya, legend and records state that a multitude of kings and devotees gathered the holy ashes, creating a vast depression that filled with water and became the sacred lotus lake. Renovated extensively across centuries by the Shravaka sanghas.',
    'Supreme Nirvana Kshetra of Lord Mahavira.',
    'Bhagwan Mahavira (Charan Paduka), in contemplative Kayotsarga posture, sculpted from Black Stone Footprints (Paduka), dating to the Ancient, (Enshrined on a silver simhasana with chhatra.).',
    '{"morning":"05:00 - 12:30 PM (Morning Abhishek, Pakhsal & Jin Puja)","evening":"05:00 PM - 19:30 (Sandhya Darshan & Deep Aradhana)","notes":"Temple opens early for morning pakhsal; visitors are requested to wear traditional clean clothes."}'::jsonb,
