(
    'mahavirji',
    'Shri Mahavirji Atishaya Kshetra',
    'श्री महावीरजी अतिशय क्षेत्र',
    ARRAY['Chandanpur Mahavirji', 'Gambhir Mahavirji']::text[],
    'atishay_kshetra',
    'Digambara',
    'Rajasthan',
    'Karauli',
    'Karauli',
    '322241',
    'Shri Mahavirji Atishaya Kshetra, Karauli, District Karauli, Rajasthan - 322241',
    26.6955,
    76.9302,
    'https://www.google.com/maps/search/?api=1&query=26.6955,76.9302',
    'Shri Mahavirji Atishaya Kshetra is an auspicious Digambar Jain pilgrimage destination situated in Karauli, Rajasthan. Foremost Digambar Atishaya Kshetra in Eastern Rajasthan, located along the sandy banks of the Gambhir River. Houses the miraculous ancient sand-stone idol of Lord Mahavira (discovered buried in a hillock) featuring rich terracotta hues and exceptional post-Gupta stylistic austerity.',
    'Historically called Chandanpur, the sacred image was unearthed by local cowherd Kripa Ram in the 17th century. The grand temple complex was constructed by Digambar sravaka Diwan Amar Chand Bilala under Jaipur State patronage. In subsequent decades, legal suits were instituted by Shwetambar litigants attempting to claim ownership and alter the denomination of Shri Mahavirji. The courts conclusively dismissed these claims after reviewing Jaipur Royal Sanads, 17th-century Bhattaraka consecration documents, unclad Digambar Padmasana iconography, and unbroken management by the Digambar Jain Atishaya Kshetra Shri Mahavirji Prabandhakarini Committee, permanently affirming its pristine Digambar status.',
    'Premier Digambar Atishaya Kshetra of Northern India.',
    'Bhagwan Mahavira (Padmasana), in contemplative Padmasana (Seated) posture, sculpted from Terracotta-tinted Sandstone, dating to the c. 11th Century CE, (Pristine unclad Digambar Padmasana posture without metallic Angi or artificial glass eyes, strictly complying with Digambar canonical Pratishtha Shastras.).',
    '{"morning":"05:00 - 12:30 PM (Morning Abhishek, Pakhsal & Jin Puja)","evening":"05:00 PM - 21:30 (Sandhya Darshan & Deep Aradhana)","notes":"Temple opens early for morning pakhsal; visitors are requested to wear traditional clean clothes."}'::jsonb,
    ARRAY['Digambar Dharamshala', 'Shuddh Jain Bhojanshala', 'Drinking Water', 'Pilgrim Rest Hall', 'Vehicle Parking']::text[],
