    'Champapuri Panch Kalyanak Kshetra is an auspicious Digambar Jain pilgrimage destination situated in Bhagalpur (Champanagar), Bihar. Ancient capital of the Anga Mahajanapada and sacred Panch Kalyanak Kshetra of Lord Vasupujya (where all five lifecycle kalyanakas: Garbha, Janma, Tapa, Kevalgyan, and Moksha occurred). Mentioned prominently in Buddhist and Jain canonical texts as a center of the Mauryan and Shunga periods.',
