    'https://www.google.com/maps/search/?api=1&query=29.1612,78.0181',
    'Hastinapur Digambar Jain Tirthakshetra is an auspicious Digambar Jain pilgrimage destination situated in Hastinapur, Uttar Pradesh. One of the most illustrious historical capitals of ancient India, situated on the ancient banks of the Ganga. Sacred birthplace and Kalyanaka Kshetra of three consecutive Tirthankars (16th Shantinatha, 17th Kunthunatha, and 18th Aranath). Also celebrated as the site where the first Tirthankar Rishabhanatha broke his 400-day fast (Akshaya Tritiya).',
    'Archaeological excavations directed by B. B. Lal (ASI, 1950–52) confirmed continuous habitation from the Painted Grey Ware (PGW) period (c. 1100–800 BCE). The Digambar Bada Mandir complex contains shrines dating from 1801 CE onwards with older medieval icons recovered from surrounding mounds.',
    'Kalyanaka Kshetra of three Tirthankars and holy Akshaya Tritiya site.',
    'Bhagwan Shantinatha, in contemplative Padmasana (Seated) posture, measuring approximately 4.5 feet, sculpted from White Makrana Marble, dating to the 1801 CE (Medieval origins), (Deer emblem (Mriga Lanchan) sculpted at base.).',
    '{"morning":"05:30 - 12:30 PM (Morning Abhishek, Pakhsal & Jin Puja)","evening":"05:00 PM - 20:30 (Sandhya Darshan & Deep Aradhana)","notes":"Temple opens early for morning pakhsal; visitors are requested to wear traditional clean clothes."}'::jsonb,
