    21.5266,
    70.5222,
    'https://www.google.com/maps/search/?api=1&query=21.5266,70.5222',
    'Girnar Urjayanta Hill (Neminatha 5th Tonk) is an auspicious Digambar Jain pilgrimage destination situated in Junagadh, Gujarat. Celebrated ancient Siddha Kshetra of the 22nd Tirthankar Lord Neminatha, who attained Diksha, Kevalgyan, and supreme Nirvana atop the sheer crags of Urjayanta mountain. The highest peak (5th Tonk) enshrines the sacred rock-cut foot impressions (Charan Paduka) of Lord Neminatha. The sanctum is the subject of a high-profile dispute regarding unauthorized idol installations and harassment of Digambar pilgrims.',
    'Celebrated in classical Sanskrit, Prakrit, and Apabhramsha epics including Tiloyapannatti (Acharya Yativrishabha) and Harivamsa Purana (Acharya Jinasena, 783 CE). The foot-hills preserve the rock edicts of Emperor Ashoka and Rudradaman, proving continuous historical sanctity from the 3rd century BCE. The mountain was patronized extensively under the Western Chalukyas, Solanki, and Vaghela monarchs.',
    'Supreme Siddha Kshetra of Lord Neminatha and penance place of Acharya Dharasena who taught the Shatkhandagama.',
    'Bhagwan Neminatha (Charan Paduka), in contemplative Kayotsarga posture, sculpted from Natural Granite Rock Paduka, dating to the Ancient, (Shankha (Conch) emblem and inscription associated with Neminatha.).',
    '{"morning":"05:00 - 12:30 PM (Morning Abhishek, Pakhsal & Jin Puja)","evening":"05:00 PM - 18:00 (Ropeway & Hill gates) (Sandhya Darshan & Deep Aradhana)","notes":"Temple opens early for morning pakhsal; visitors are requested to wear traditional clean clothes."}'::jsonb,
