    'Sacred Digambar Jain pilgrimage center located in Akola, Maharashtra. Revered as an ancient Atishaya Kshetra dedicated to Lord Parshvanatha, the sanctuary preserves venerable Vitaraga Jinabimba sculptures, traditional stone architecture, and serene devotional heritage frequented by pilgrims across India.',
