    24.0722,
    73.6974,
    'https://www.google.com/maps/search/?api=1&query=24.0722,73.6974',
    'Kesariyaji Rishabhdeo Tirth (Dhulev) is an auspicious Digambar Jain pilgrimage destination situated in Rishabhdeo (Dhulev), Rajasthan. Magnificent ancient tirtha enshrining a 9th-century colossal black marble idol of Bhagwan Rishabhdev in Padmasana posture. Widely venerated for massive offerings of pure saffron (Kesar), earning the sanctuary the beloved title ''Kesariyaji''. The local indigenous Bhil community worships the idol with heartfelt devotion as ''Kalaji'' or ''Kaliya Baba''. The temple has been subjected to administrative takeover by the Rajasthan State Devasthan Department, curtailing traditional Digambar autonomy and ritual prakshal.',
    'The sanctuary boasts a rich epigraphical history dating from the 9th to the 17th centuries under the patronage of the Maharanas of Mewar. Mewar rulers preserved royal firmans ensuring customary Jain worship. Following the merger of princely states, the Rajasthan State Government assumed direct bureaucratic control under the Devasthan Department, prompting decades of constitutional litigation.',
    'One of the most revered Atishaya Kshetras in Western India, sacred to Jains and revered by tribal communities.',
    'Bhagwan Rishabhdev (Kesariyaji), in contemplative Padmasana (Seated) posture, sculpted from Polished Black Schist Stone, dating to the 9th Century CE, (Unclad Digambar Adinatha seated with Bull emblem and flowing hair locks (Jata).).',
    '{"morning":"05:30 - 12:30 PM (Morning Abhishek, Pakhsal & Jin Puja)","evening":"05:00 PM - 20:00 (Sandhya Darshan & Deep Aradhana)","notes":"Temple opens early for morning pakhsal; visitors are requested to wear traditional clean clothes."}'::jsonb,
