    'Chawleshwar Shri Parshvanath Digambar Jain Deshnodaya Atishaya Kshetra is an auspicious Digambar Jain pilgrimage destination situated in Chainpura (Near Bhilwara), Rajasthan. Revered ancient Digambar Atishaya Kshetra situated near Chainpura in Bhilwara district, Rajasthan, enshrining the miraculous seated idol of Moolnayak Bhagwan Parshvanatha. The sacred tirtha has faced serious encroachment and boundary usurpation attempts by anti-social elements, prompting massive representations by the Sakal Digambar Jain Samaj to the Bhilwara District Collector and Police Administration for urgent demarcation, protection, and legal enforcement.',
    'An ancient Digambar pilgrimage center in the Mewar territory near Bhilwara, celebrated for miraculous occurrences (atishayas) associated with Moolnayak Parshvanath. Consecrated according to classical Digambar traditions, the sanctuary has been preserved by local Jain shravakas and trusts for generations.',
