    86.1345,
    'https://www.google.com/maps/search/?api=1&query=23.9627,86.1345',
    'Shri Sammed Shikharji (Parasnath Hill) is an auspicious Digambar Jain pilgrimage destination situated in Madhuban (Parasnath), Jharkhand. The holiest and supreme Siddha Kshetra of Jainism. Atop the sacred crags of Parasnath Hill, 20 out of the 24 Tirthankaras—including Bhagwan Parshvanatha, Bhagwan Sambhavanatha, and Bhagwan Shantinatha—attained supreme Nirvana (liberation). The 27-kilometer sacred pilgrimage parikrama across the peaks has been walked by millions of ascetics and householders for millennia. The sacred mountain has faced grave threats from government eco-tourism notifications and commercial encroachment.',
    'Celebrated in the earliest canonical scriptures, including Acharanga Sutra, Kalpa Sutra, and Tiloyapannatti. Centuries of continuous pilgrimage, medieval inscriptions on each tonk, and the historic Privy Council judgment of 1930 establish the absolute sanctity and ownership of the hill as a Jain religious sanctuary.',
    'Supreme Nirvana Kshetra of Jainism where 20 Tirthankaras and billions of ascetics attained Moksha.',
    'Bhagwan Parshvanatha (20 Tirthankara Padukas), in contemplative Kayotsarga posture, sculpted from Sacred White & Black Marble Padukas, dating to the Ancient, (Enshrined on the highest pinnacle (Parasnath Peak, 1365m).).',
    '{"morning":"04:00 - 12:30 PM (Morning Abhishek, Pakhsal & Jin Puja)","evening":"05:00 PM - 18:00 (Vandana hours) (Sandhya Darshan & Deep Aradhana)","notes":"Temple opens early for morning pakhsal; visitors are requested to wear traditional clean clothes."}'::jsonb,
