    'Gopachal Parvat Rock-Cut Tirth (Gwalior Fort)',
    'गोपाचल पर्वत शैल-उत्कीर्ण तीर्थ (ग्वालियर किला)',
    ARRAY['Gopachal Atishaya Kshetra', 'Gwalior Rock Colossi', 'Ek Patthar Ki Baoli']::text[],
    'historical_site',
    'Digambara',
    'Madhya Pradesh',
