    'Gopachal Parvat Rock-Cut Tirth (Gwalior Fort), Gwalior, District Gwalior, Madhya Pradesh - 474001',
    26.231,
    78.1697,
    'https://www.google.com/maps/search/?api=1&query=26.231,78.1697',
    'Gopachal Parvat Rock-Cut Tirth (Gwalior Fort) is an auspicious Digambar Jain pilgrimage destination situated in Gwalior, Madhya Pradesh. World-renowned 15th-century rock-cut Digambar colossi carved directly into the sheer vertical cliffs of Gwalior Fort under the Tomar King Dungar Singh. Enshrines the monumental 57-foot seated Padmasana colossus of Lord Parshvanatha. The monument faces urgent conservation concerns due to urban encroachments at the cliff foot, garbage dumping, and past Mughal-era defacements.',
    'Carved between 1440 and 1473 CE under royal Tomar patronage guided by Digambar Bhattarakas (Gunabhadra and Yashokeerti). In 1527, Mughal emperor Babur ordered their desecration, but the massive scale prevented complete destruction. In recent decades, urban residential creep along the fort base has threatened the site.',
    'Paramount rock-cut Atishaya Kshetra featuring the tallest seated Tirthankara colossus in the world.',
    'Bhagwan Parshvanatha (57-ft Padmasana Colossus), in contemplative Padmasana (Seated) posture, sculpted from Natural Sandstone Living Rock, dating to the 15th Century CE, (Enormous serpent canopy with serene Digambar contemplation.).',
    '{"morning":"06:00 - 12:30 PM (Morning Abhishek, Pakhsal & Jin Puja)","evening":"05:00 PM - 18:00 (Sandhya Darshan & Deep Aradhana)","notes":"Temple opens early for morning pakhsal; visitors are requested to wear traditional clean clothes."}'::jsonb,
