    'Paved courtyard offering convenient ground-level pedestrian access throughout the temple complex.',
    '{"railway":"Gwalior Railway Station (connected to major junction via North Central / Western / South Western Railways)","airport":"Rajmata Vijaya Raje Scindia Airport, Gwalior (GWL)","road":"Connected via State & National Highway network; local bus and taxi services available from Gwalior"}'::jsonb,
