    'mp-jabalpur-jain',
    'Hanumantal Bada Digambar Jain Mandir',
    'हनुमानताल बड़ा दिगम्बर जैन मंदिर (जबलपुर)',
    ARRAY[]::text[],
    'temple',
    'Digambara',
    'Madhya Pradesh',
    'Jabalpur',
    'Jabalpur',
    '482001',
    'Hanumantal Bada Digambar Jain Mandir, Jabalpur, District Jabalpur, Madhya Pradesh - 482001',
    23.1815,
    79.9864,
    'https://www.google.com/maps/search/?api=1&query=23.1815,79.9864',
    'Hanumantal Bada Digambar Jain Mandir is an auspicious Digambar Jain pilgrimage destination situated in Jabalpur, Madhya Pradesh. Hanumantal Bada Jain Mandir is the paramount historic Digambar Jain temple complex of Jabalpur, situated serenely on the edge of Hanumantal lake. Originally erected in 1686 CE (Vikram Samvat 1743), it houses 22 distinct sanctums (vedis), making it the largest historic Jain temple complex in central India.',
    'Erected in 1686 CE by the Jain community on the embankment of the historic Hanumantal water body, this vast fortress-like shrine preserves over 22 sanctums housing idols dating from the 10th century Kalachuri period to the Maratha and Bundela eras. It houses a celebrated ancient Shastra Bhandar (Grantha Bhandar) containing rare palm-leaf and paper illuminated manuscripts. Rabindranath Tagore stayed here in 1930 and immortalized its serene spiritual atmosphere in his memoirs.',
    'Premier Atishaya Kshetra of Jabalpur and major center of Digambar Jain learning and manuscript preservation in Mahakoshal.',
    'Bhagwan Adinatha (Rishabhanatha), in contemplative Padmasana (Seated) posture, measuring approximately 3.5 feet, sculpted from Black Touchstone (Kasauti Pashan), dating to the 10th–11th Century CE (Kalachuri Dynasty), (Exquisitely carved in deep black touchstone with cascading shoulder jatas, bull emblem (vrishabha) on pedestal, flanked by Gomukha Yaksha and Chakreshwari Devi.).',
    '{"morning":"06:00 - 12:30 PM (Morning Abhishek, Pakhsal & Jin Puja)","evening":"05:00 PM - 20:30 (Sandhya Darshan & Deep Aradhana)","notes":"Temple opens early for morning pakhsal; visitors are requested to wear traditional clean clothes."}'::jsonb,
    ARRAY['Digambar Dharamshala', 'Shuddh Jain Bhojanshala', 'Drinking Water', 'Pilgrim Rest Hall', 'Vehicle Parking']::text[],
    'Paved courtyard offering convenient ground-level pedestrian access throughout the temple complex.',
    '{"railway":"Jabalpur Railway Station (connected to major junction via North Central / Western / South Western Railways)","airport":"Raja Bhoj Airport, Bhopal (BHO) / Gwalior Airport (GWL)","road":"Connected via State & National Highway network; local bus and taxi services available from Jabalpur"}'::jsonb,
