(
    'dilwara',
    'Dilwara Marble Jain Temple Complex (Mount Abu)',
    'दिलवाड़ा संगमरमर जैन मंदिर समूह (माउंट आबू)',
    ARRAY['Mount Abu Dilwara Temples', 'Vimal Vasahi & Luna Vasahi', 'Devalwara', 'देवलवाड़ा', 'आबू पर्वत जैन तीर्थ']::text[],
    'temple_complex',
    'Digambara',
    'Rajasthan',
    'Sirohi',
    'Mount Abu',
    '307501',
    'Dilwara Marble Jain Temple Complex (Mount Abu), Mount Abu, District Sirohi, Rajasthan - 307501',
    24.6006,
    72.7224,
    'https://www.google.com/maps/search/?api=1&query=24.6006,72.7224',
    'Dilwara Marble Jain Temple Complex (Mount Abu) is an auspicious Digambar Jain pilgrimage destination situated in Mount Abu, Rajasthan. A world-renowned pinnacle of medieval Indian marble temple architecture perched atop Mount Abu in Rajasthan. Built between the 11th and 13th centuries CE, the sacred complex comprises five monumental sanctuaries: Vimal Vasahi (consecrated 1031 CE by Dandapadati Vimala Shah to Lord Rishabhanatha), Luna Vasahi (consecrated 1230 CE by ministers Vastupala and Tejapala to Lord Neminatha), Pittalhar (Adinatha with massive brass colossus), Parshvanatha, and Mahavira Swami. Documented by the Archaeological Survey of India in ''Archaeology in India'' (GoI 1967, p. 46) for its historic structural restoration and marble chemical conservation.',
    'The Dilwara temples were established under the Chaulukya (Solanki) and Vaghela rulers of Gujarat. Vimal Vasahi was founded in 1031 CE by Vimala Shah, governor of Chandravati and commander of King Bhimadeva I, seeking spiritual expiation. Luna Vasahi was consecrated in 1230 CE by the eminent Porwad brothers Vastupala and Tejapala in memory of their brother Luniga, supervised by master architect Sobhandeva. During the 14th century, the temples suffered damage during regional campaigns but underwent meticulous restoration in 1321 CE by Lalla and Vijada. In the 20th century, the Archaeological Survey of India undertook specialized structural consolidation of the cantilevered marble domes, bracket lintels, and intricate hanging pendants (padmasila), as documented in ASI centenary reports.',
    'One of the most sacred and artistically revered Jain Tirthas in western India, celebrated globally as the ultimate triumph of stone carving devotion.',
    'Bhagwan Rishabhanatha (Vimal Vasahi) & Neminatha (Luna Vasahi), in contemplative Padmasana (Seated) posture, sculpted from Pure White Makrana Marble, dating to the 11th–13th Century CE, (Serene meditative posture seated on carved lion thrones, flanked by fly-whisk bearers and celestial vidyadharas.).',
    '{"morning":"12:00 - 12:30 PM (Morning Abhishek, Pakhsal & Jin Puja)","evening":"05:00 PM - 17:00 (Pilgrims: 06:00 (Sandhya Darshan & Deep Aradhana)","notes":"Temple opens early for morning pakhsal; visitors are requested to wear traditional clean clothes."}'::jsonb,
    ARRAY['Digambar Dharamshala', 'Shuddh Jain Bhojanshala', 'Drinking Water', 'Pilgrim Rest Hall', 'Vehicle Parking']::text[],
    'Hillside or elevated terrain with stone-carved steps; doli/chair palanquin assistance is generally available for elderly devotees.',
    '{"railway":"Mount Abu Railway Station (connected to major junction via North Central / Western / South Western Railways)","airport":"Maharana Pratap Airport, Udaipur (UDR)","road":"Connected via State & National Highway network; local bus and taxi services available from Mount Abu"}'::jsonb,
    'Inquire at Local Digambar Jain Prabandhakarini Committee Office',
    'https://realjainism.bot.cd/tirths/dilwara',
    'https://rllagzfmqpkzjhxnzxpf.supabase.co/storage/v1/object/public/tirth-photos/Dilwara%20Marble%20Jain%20Temple%20Complex%20(Mount%20Abu).png',
    'published'
),
