    'Chittorgarh Fort Jain Temples & Kirti Stambha (Tower of Fame), Chittorgarh Fort, District Chittorgarh, Rajasthan - 312001',
    24.8887,
    74.6269,
    'https://www.google.com/maps/search/?api=1&query=24.8887,74.6269',
    'Chittorgarh Fort Jain Temples & Kirti Stambha (Tower of Fame) is an auspicious Digambar Jain pilgrimage destination situated in Chittorgarh Fort, Rajasthan. A monumentally significant fortified ensemble within Chittorgarh Fort featuring the world-famous 12th-century Kirti Stambha (Tower of Fame) and the 11th-century Satbis Deori (27 shrines) temple complex. The 22-meter-high, seven-storeyed Kirti Stambha was commissioned by the Digambar Jain merchant Jeevandhar (Jija Bhagerwala) under the spiritual guidance of Bhattaraka Dharmachandra, dedicated to Bhagwan Adinatha. Conserved by the Archaeological Survey of India and documented in GoI centenary records (''Archaeology in India'', 1967).',
    'Chittorgarh (ancient Chitrakoot) served as an eminent sanctuary and regional seat of Digambar Jain learning and monastic culture. In the late 12th century (c. 1190–1200 CE), merchant Jeevandhar, son of Solakh of the Bhagerwal community, commissioned the soaring Kirti Stambha to proclaim the glory of the Tirthankara dharma. The tower was completed by his son Punyasimha. In 1468 CE (VS 1525), following lightning damage, the monument was carefully repaired by local Jain guilds under Mewar royal patronage. The fort also houses the historic Satbis Deori complex containing 27 shrines. The Archaeological Survey of India has carried out structural stabilization and lightning arrestor installations on the tower.',
    'Paramount monument of Digambar Jain architectural pride in Rajasthan and prominent UNESCO World Heritage Site landmark.',
    'Bhagwan Adinatha (Rishabhadeva - Chaumukha & Colossal Carvings), in contemplative Kayotsarga (Standing) & Padmasana (Seated) posture, sculpted from Carved Local Sandstone, dating to the 12th Century CE, (Distinctive Digambar vitaraga features; 5-foot standing Adinatha figure prominently enshrined on the lower story.).',
    '{"morning":"06:00 - 12:30 PM (Morning Abhishek, Pakhsal & Jin Puja)","evening":"05:00 PM - 18:00 (Fort entry) (Sandhya Darshan & Deep Aradhana)","notes":"Temple opens early for morning pakhsal; visitors are requested to wear traditional clean clothes."}'::jsonb,
    ARRAY['Digambar Dharamshala', 'Shuddh Jain Bhojanshala', 'Drinking Water', 'Pilgrim Rest Hall', 'Vehicle Parking']::text[],
    'Hillside or elevated terrain with stone-carved steps; doli/chair palanquin assistance is generally available for elderly devotees.',
    '{"railway":"Chittorgarh Fort Railway Station (connected to major junction via North Central / Western / South Western Railways)","airport":"Maharana Pratap Airport, Udaipur (UDR)","road":"Connected via State & National Highway network; local bus and taxi services available from Chittorgarh Fort"}'::jsonb,
