(
    'dl-qutb-jain-spolia',
    'Qutb Complex Ancient Jain Sanctuaries & Spolia (Quwwat-ul-Islam)',
    'कुतुब परिसर प्राचीन जैन मंदिर अवशेष एवं दालान (कुव्वत-उल-इस्लाम)',
    ARRAY['27 Jain and Hindu Temples Site', 'Lal Kot Jain Remains', 'Qila Rai Pithora Jain Spolia', 'Quwwat-ul-Islam Cloisters']::text[],
    'temple_complex',
    'Digambara',
    'Delhi',
    'South Delhi',
    'Mehrauli',
    '470001',
    'Qutb Complex Ancient Jain Sanctuaries & Spolia (Quwwat-ul-Islam), Mehrauli, District South Delhi, Delhi - 470001',
    28.5244,
    77.1855,
    'https://www.google.com/maps/search/?api=1&query=28.5244,77.1855',
    'Qutb Complex Ancient Jain Sanctuaries & Spolia (Quwwat-ul-Islam) is an auspicious Digambar Jain pilgrimage destination situated in Mehrauli, Delhi. The foundational archaeological site of medieval Delhi within Lal Kot (Qila Rai Pithora). The colonnaded cloisters and courtyard surrounding the Quwwat-ul-Islam Mosque were assembled from the architectural spolia of 27 dismantled pre-Islamic Hindu and Digambar Jain temples, explicitly recorded in the 1191–1193 CE Arabic gateway inscription. Detailed by 19th-century archaeologists Carr Stephen, Alexander Cunningham, and James Fergusson, the site preserves surviving Digambar iconography including carved Tirthankara panels, bell-and-chain pillar motifs, and corbelled lantern ceilings.',
    'During the Tomara and Chauhan dynasties (10th–12th century CE), Lal Kot and surrounding Dhillika flourished as a major center of Digambar Jain culture, trade, and temple building. Following the conquest of Delhi by Qutb-ud-din Aibak in 1191–1192 CE (587 Hijri), materials from twenty-seven prominent temples within the citadel were dismantled and re-erected to construct the congregational mosque. Major-General Alexander Cunningham identified that the majority of the surviving ornate pillars belonged to Jain temples due to the distinctive rows of bells on chains, floral arabesques, and defaced Tirthankara reliefs on lintel brackets. Archaeological excavations conducted under J.D. Beglar in 1871 revealed the original pre-Islamic temple plinths and platforms directly beneath the mosque pavement.',
    'Of monumental archaeological and epigraphical importance, serving as physical testimony to the flourishing Digambar Jain architectural landscape of pre-Sultanate Dhillika (Delhi).',
    'Ancient Tomara-Chauhan Tirthankara Panels, in contemplative Padmasana (Seated) posture, sculpted from Carved Delhi Quartzite & Red Sandstone, dating to the 10th–12th Century CE, (Surviving relief carvings of seated Tirthankaras in Padmasana with attendants and Shrivatsa marks on roofing slabs, lintels, and pillar bases.).',
    '{"morning":"06:00 - 12:30 PM (Morning Abhishek, Pakhsal & Jin Puja)","evening":"05:00 PM - 18:00 (ASI Protected Site) (Sandhya Darshan & Deep Aradhana)","notes":"Temple opens early for morning pakhsal; visitors are requested to wear traditional clean clothes."}'::jsonb,
    ARRAY['Digambar Dharamshala', 'Shuddh Jain Bhojanshala', 'Drinking Water', 'Pilgrim Rest Hall', 'Vehicle Parking']::text[],
    'Paved courtyard offering convenient ground-level pedestrian access throughout the temple complex.',
    '{"railway":"Mehrauli Railway Station (connected to major junction via North Central / Western / South Western Railways)","airport":"Nearest state capital civil airport with domestic flight connectivity","road":"Connected via State & National Highway network; local bus and taxi services available from Mehrauli"}'::jsonb,
