    'published'
),
(
    'dl-lal-mandir',
    'Shri Digambar Jain Lal Mandir (Red Temple, Chandni Chowk)',
    'श्री दिगंबर जैन लाल मंदिर (चाँदनी चौक, लाल किला)',
    ARRAY['Lal Mandir', 'Urdu Mandir', 'Camp Temple', 'Red Temple Delhi', 'Chandni Chowk Digambar Jain Mandir']::text[],
    'atishay_kshetra',
    'Digambara',
    'Delhi',
    'Central Delhi',
    'Old Delhi (Shahjahanabad)',
    '470001',
    'Shri Digambar Jain Lal Mandir (Red Temple, Chandni Chowk), Old Delhi (Shahjahanabad), District Central Delhi, Delhi - 470001',
    28.6558,
    77.2309,
    'https://www.google.com/maps/search/?api=1&query=28.6558,77.2309',
    'Shri Digambar Jain Lal Mandir (Red Temple, Chandni Chowk) is an auspicious Digambar Jain pilgrimage destination situated in Old Delhi (Shahjahanabad), Delhi. The oldest and best-known Digambar Jain temple in Delhi, situated directly opposite the Red Fort at the entrance to Netaji Subhash Marg and Chandni Chowk. Established in 1656 CE during the reign of Mughal Emperor Shah Jahan, it originated as the ''Urdu Mandir'' (Camp Temple) for Jain military officers and imperial merchants. Built in striking red sandstone, the complex houses ancient Jinabimbas dating from the 10th–15th centuries and the renowned Charity Birds Hospital (Jain Chidiya Aspatal) established in 1956.',
    'When Emperor Shah Jahan shifted the Mughal capital from Agra to Shahjahanabad (Delhi) in 1648, a contingent of Jain cavalry officers and royal treasurers was granted land to establish their camp opposite the imperial citadel. In 1656, an imperial officer installed a sacred image of Lord Parshvanatha in a tent sanctuary, which gradually expanded into a permanent red sandstone structure known as the Urdu Mandir. During the later Mughal period, sacred metal and stone Tirthankara idols from ancient temples in Mewar and Gwalior were brought here for preservation. In 1800–1807, Raja Harsukh Rai and community leaders renovated the sanctum, and in the early 20th century, the imposing red sandstone shikhara was added. Carr Stephen (1876) notes the prominent commercial and spiritual status of the Digambar merchant community surrounding Chandni Chowk.',
    'Premier spiritual and institutional landmark of the Digambar Jain community in northern India, receiving hundreds of thousands of pilgrims annually.',
    'Bhagwan Rishabhanatha (Adinath), in contemplative Padmasana (Seated) posture, measuring approximately 3 feet, sculpted from Black Kasauti Stone, dating to the Medieval (c. 11th–12th Century CE), (Ancient seated Vitaraga idol with bull lanchhana, accompanied by historical brass idols of Parshvanatha and Chandraprabhu.).',
    '{"morning":"05:30 - 12:30 PM (Morning Abhishek, Pakhsal & Jin Puja)","evening":"05:00 PM - 11:30, 18:00 (Sandhya Darshan & Deep Aradhana)","notes":"Temple opens early for morning pakhsal; visitors are requested to wear traditional clean clothes."}'::jsonb,
    ARRAY['Digambar Dharamshala', 'Shuddh Jain Bhojanshala', 'Drinking Water', 'Pilgrim Rest Hall', 'Vehicle Parking']::text[],
    'Paved courtyard offering convenient ground-level pedestrian access throughout the temple complex.',
    '{"railway":"Old Delhi (Shahjahanabad) Railway Station (connected to major junction via North Central / Western / South Western Railways)","airport":"Nearest state capital civil airport with domestic flight connectivity","road":"Connected via State & National Highway network; local bus and taxi services available from Old Delhi (Shahjahanabad)"}'::jsonb,
