    'published'
),
(
    'dl-naya-mandir',
    'Shri Digambar Jain Naya Mandir (Dharampura, Chandni Chowk)',
    'श्री दिगंबर जैन नया मंदिर (धर्मपुरा, चाँदनी चौक)',
    ARRAY['Raja Harsukh Rai Temple', 'Dharampura Jain Mandir', 'Naya Mandir Shahjahanabad']::text[],
    'atishay_kshetra',
    'Digambara',
    'Delhi',
    'Central Delhi',
    'Old Delhi (Dharampura)',
    '454001',
    'Shri Digambar Jain Naya Mandir (Dharampura, Chandni Chowk), Old Delhi (Dharampura), District Central Delhi, Delhi - 454001',
    28.651,
    77.227,
    'https://www.google.com/maps/search/?api=1&query=28.651,77.227',
    'Shri Digambar Jain Naya Mandir (Dharampura, Chandni Chowk) is an auspicious Digambar Jain pilgrimage destination situated in Old Delhi (Dharampura), Delhi. A monumental Digambar Jain temple in Dharampura, Old Delhi, constructed in 1807 CE (VS 1864) by Raja Harsukh Rai, royal treasurer to Mughal Emperor Akbar II. Revered as the first Jain temple in the Mughal imperial capital to be granted an official imperial firman permitting the erection of stone shikharas (spires), which had been prohibited in Delhi for centuries. The temple houses an extraordinary subterranean Jnana Bhandar preserving priceless medieval Digambar manuscripts.',
    'Raja Harsukh Rai, an influential Agarwala Digambar Jain merchant and imperial treasurer, secured a special royal decree (firman) from Mughal Emperor Akbar II allowing the construction of soaring stone shikharas in the walled city of Shahjahanabad. The grand consecration ceremony (Panchakalyanaka Pratishtha) in 1807 was celebrated with unprecedented splendor, attended by Digambar sanghas from across northern and western India. Raja Harsukh Rai also established a subterranean Jnana Bhandar (scriptural repository) to safeguard rare palm-leaf and handmade paper manuscripts, including illuminated texts of the Samayasara and Uttarapurana with gold calligraphy.',
    'Renowned for its architectural magnificence, imperial historical significance, and one of northern India''s richest private collections of Digambar Jain manuscripts (Jnana Bhandar).',
    'Bhagwan Parshvanatha, in contemplative Padmasana (Seated) posture, measuring approximately 3.5 feet, sculpted from White Makrana Marble, dating to the 1807 CE (Constituted with ancient Pratimas), (Exquisitely polished marble image with seven-hooded serpent canopy (Dharanendra nagafana) and attendant Yaksha-Yakshi carvings.).',
    '{"morning":"06:00 - 12:30 PM (Morning Abhishek, Pakhsal & Jin Puja)","evening":"05:00 PM - 11:30, 17:30 (Sandhya Darshan & Deep Aradhana)","notes":"Temple opens early for morning pakhsal; visitors are requested to wear traditional clean clothes."}'::jsonb,
    ARRAY['Digambar Dharamshala', 'Shuddh Jain Bhojanshala', 'Drinking Water', 'Pilgrim Rest Hall', 'Vehicle Parking']::text[],
