    'Sacred Digambar Jain pilgrimage center located in Shimla, Himachal Pradesh. Revered as an ancient Atishaya Kshetra dedicated to Lord Rishabhanatha (Adinath), the sanctuary preserves venerable Vitaraga Jinabimba sculptures, traditional stone architecture, and serene devotional heritage frequented by pilgrims across India.',
