    'https://www.google.com/maps/search/?api=1&query=24.75,78.11',
    'Budhi Chanderi Ancient Forest Tirth is an auspicious Digambar Jain pilgrimage destination situated in Chanderi, Madhya Pradesh. A dramatic ruined medieval temple city situated in dense forest approximately 15 km northwest of modern Chanderi. Contains the surviving remnants of over 20 stone Jain temples dating from the 10th to 12th centuries CE under the Gurjara-Pratiharas and Chandelas, celebrated in Chapter 13 of Dr. Kailash Chand Jain''s treatise.',
    'Budhi Chanderi was the original metropolis of the Chanderi region and one of the earliest prominent seats (pithas) of the Digambar Mula Sangha Kundakundanvaya. Scores of inscribed tirthankara pedestals and monolithic pillars bear dates ranging from Samvat 1050 to 1250. In the late medieval period, the population relocated to current Chanderi, leaving these sacred stone sanctuaries sheltered within the Vindhyan forests.',
    'Venerated ancient Digambar Atishaya Kshetra documented in medieval Tirtha-Malas and Bhattaraka records.',
    'Bhagwan Parshvanatha & Rishabhdeva, in contemplative Padmasana (Seated) posture, measuring approximately Colossal monolithic reliefs, sculpted from Buff Sandstone, dating to the 11th Century CE, (Multi-hooded serpent canopy, Yaksha Dharanendra, and Yakshi Padmavati carved in high relief.).',
    '{"morning":"08:00 - 12:30 PM (Morning Abhishek, Pakhsal & Jin Puja)","evening":"05:00 PM - 17:00 (Forest sanctuary) (Sandhya Darshan & Deep Aradhana)","notes":"Temple opens early for morning pakhsal; visitors are requested to wear traditional clean clothes."}'::jsonb,
