    78.2394,
    'https://www.google.com/maps/search/?api=1&query=26.5864,78.2394',
    'Sihoniya Shantinatha Digambar Atishaya Kshetra is an auspicious Digambar Jain pilgrimage destination situated in Sihoniya, Madhya Pradesh. The ancient capital of the Kachchhapaghata dynasty (11th century CE), famous for its monumental 15-foot high seated monolithic sandstone idol of Lord Shantinatha. Detailed in Chapter 13 of Dr. Kailash Chand Jain''s treatise as one of northern Madhya Pradesh''s supreme medieval sculpting achievements.',
    'Founded as the political seat of the Kachchhapaghata ruler Kirtiraja and his successors in the 11th century CE. An inscription dated Samvat 1072 records the consecration of the great Shantinatha idol by merchant leaders under Digambar monastic guidance. Surrounding fields continue to yield ornate Tirthankara bronzes, pillars, and inscriptions.',
    'Revered as an miraculous Atishaya Kshetra where prayers for peace and liberation are answered.',
    'Bhagwan Shantinatha, in contemplative Padmasana (Seated) posture, measuring approximately 15 feet (4.5 meters), sculpted from Red Sandstone, dating to the 1015 CE (Samvat 1072), (Deer cognizance (lanchhana) inscribed on the lotus throne; flanked by Indra and celestial attendants.).',
    '{"morning":"06:00 - 12:30 PM (Morning Abhishek, Pakhsal & Jin Puja)","evening":"05:00 PM - 19:00 (Sandhya Darshan & Deep Aradhana)","notes":"Temple opens early for morning pakhsal; visitors are requested to wear traditional clean clothes."}'::jsonb,
