    22.3667,
    75.4,
    'https://www.google.com/maps/search/?api=1&query=22.3667,75.4',
    'Mandavgadh (Mandu) Digambar Jain Bada Mandir & Atishaya Kshetra is an auspicious Digambar Jain pilgrimage destination situated in Mandu, Madhya Pradesh. A renowned medieval hill-fort pilgrimage sanctuary atop the Vindhyan plateau. Detailed in historical chronicles of Central India and archaeological surveys, Mandu (ancient Mandapadurga) was a vibrant center of Digambar Jain architecture, housing rare 10th- to 15th-century Kasauti stone and marble Digambar Tirthankara colossi.',
    'Epigraphs confirm Digambar Jain shrines at Mandapadurga from the Paramara era (10th–13th centuries) through the Malwa Sultanate period. Pious Digambar Shravakas and merchant families commissioned grand stone temples, preserved sacred manuscripts in Shastra Bhandars, and hosted numerous Digambar Munis in the mountain retreats.',
    'Revered Digambar Atishaya Kshetra dedicated to Lord Suparshvanatha, visited by centuries of pilgrimage caravans across Malwa.',
    'Bhagwan Suparshvanatha, in contemplative Padmasana (Seated) posture, measuring approximately 3 feet, sculpted from White Marble & Kasauti Stone, dating to the 14th Century CE, (Seven-hooded serpent canopy and swastika symbol in pure Digambar meditative posture.).',
    '{"morning":"06:00 - 12:30 PM (Morning Abhishek, Pakhsal & Jin Puja)","evening":"05:00 PM - 18:30 (Sandhya Darshan & Deep Aradhana)","notes":"Temple opens early for morning pakhsal; visitors are requested to wear traditional clean clothes."}'::jsonb,
