    25.1611,
    75.3236,
    'https://www.google.com/maps/search/?api=1&query=25.1611,75.3236',
    'Bijolia (Vindhyavalli) Parshvanatha Tirth is an auspicious Digambar Jain pilgrimage destination situated in Bijolia, Rajasthan. The ancient holy tirtha of Vindhyavalli, celebrated for its 12th-century Parshvanatha temple and the renowned rock-cut inscription of 1170 CE composed by Gunabhadra during the reign of Chauhan king Someshvara. Highlighted in Chapter 13 of Dr. Kailash Chand Jain''s treatise.',
    'Built by the pious Digambar merchant Mahajana Lolaka in the 12th century under the spiritual guidance of the Mathura Sangha. The site contains five ancient stone shrines, step-wells (baoris), and the celebrated rock edict that preserves essential historical records of northern India.',
    'One of the supreme Parshvanatha Atishaya Kshetras in Rajasthan, known as Unhava Parshvanatha.',
    'Bhagwan Unhava Parshvanatha, in contemplative Padmasana (Seated) posture, measuring approximately 3.5 feet, sculpted from Black Sandstone, dating to the 12th Century CE, (Serpent hoods with intricately carved Dharanendra and Padmavati flanking the pedestal.).',
    '{"morning":"06:00 - 12:30 PM (Morning Abhishek, Pakhsal & Jin Puja)","evening":"05:00 PM - 19:00 (Sandhya Darshan & Deep Aradhana)","notes":"Temple opens early for morning pakhsal; visitors are requested to wear traditional clean clothes."}'::jsonb,
