    26.7025,
    75.8714,
    'https://www.google.com/maps/search/?api=1&query=26.7025,75.8714',
    'Bada Padampura Digambar Jain Atishaya Kshetra is an auspicious Digambar Jain pilgrimage destination situated in Padampura (Shivdaspura), Rajasthan. Bada Padampura is one of the most revered and miraculous Digambar Jain Atishaya Kshetras in Rajasthan, located 35 km from Jaipur. The sacred shrine houses an extraordinary 6th-century Kasauti stone (black touchstone) Padmasana idol of the 6th Tirthankara Bhagavan Padmaprabha, miraculously discovered during excavations on Vaisakh Shukla Panchami in 1944 CE.',
    'In May 1944 (Vikram Samvat 2001, Vaisakh Shukla Panchami), while digging foundation trenches in Padampura village, a pious local resident named Moola Jat discovered this divine Kasauti stone idol of Bhagavan Padmaprabha. The entire Digambar Jain community gathered from across India to consecrate the miracle idol in a grand temple complex, which has grown into a world-famous center of spiritual refuge and charity.',
    'Paramount Digambar Atishaya Kshetra in Rajasthan where hundreds of thousands of pilgrims seek spiritual peace and resolve distress through prayers before Bhagavan Padmaprabha.',
    'Bhagwan Padmaprabha (Kasauti Pashan), in contemplative Padmasana (Seated) posture, measuring approximately 2.4 feet, sculpted from Kasauti Stone (Black Touchstone), dating to the 6th Century CE, (Dhyanamudra seated in lotus posture on an intricately carved lotus pedestal with lotus (Kamala) lanchhana.).',
    '{"morning":"05:30 - 12:30 PM (Morning Abhishek, Pakhsal & Jin Puja)","evening":"05:00 PM - 21:00 (Sandhya Darshan & Deep Aradhana)","notes":"Temple opens early for morning pakhsal; visitors are requested to wear traditional clean clothes."}'::jsonb,
