    14.25,
    74.65,
    'https://www.google.com/maps/search/?api=1&query=14.25,74.65',
    'Gerusoppe (Nagire) Chaturmukha Basadi Complex is an auspicious Digambar Jain pilgrimage destination situated in Honnavar, Karnataka. The riverside royal capital of the medieval Saluva (Nagire) Jain dynasty on the banks of the Sharavathi River. Ruled in the 16th century by the legendary Jain Queen Chennabhairadevi (the ''Pepper Queen'' who reigned for 54 years). Contains the exquisite grey granite Chaturmukha Basadi, documented in Chapter 13 of Dr. Kailash Chand Jain''s treatise.',
    'Flourished from the 14th to 17th centuries as a premier maritime trading and spiritual hub of Coastal Karnataka. Queen Chennabhairadevi gave asylum to Saraswat Brahmins and constructed monumental basadis, chhatris, and Nishidhi stones, maintaining sovereign independence against Portuguese naval expeditions.',
    'Supreme historical monument of Coastal Karnataka Digambar Jain heritage.',
    'Chaturmukha Tirthankaras (Adinatha, Shantinatha, Parshvanatha, Mahavira), in contemplative Padmasana (Seated) posture, measuring approximately 4 feet each, sculpted from Grey Granite, dating to the 16th Century CE, (Four serene identical granite icons facing east, west, north, and south in the garbhagriha.).',
    '{"morning":"07:00 - 12:30 PM (Morning Abhishek, Pakhsal & Jin Puja)","evening":"05:00 PM - 18:00 (Sandhya Darshan & Deep Aradhana)","notes":"Temple opens early for morning pakhsal; visitors are requested to wear traditional clean clothes."}'::jsonb,
