    12.4419,
    79.1678,
    'https://www.google.com/maps/search/?api=1&query=12.4419,79.1678',
    'Tirumalai Neminatha Cave & Hill Complex is an auspicious Digambar Jain pilgrimage destination situated in Polur, Tamil Nadu. A monumental ancient hill sanctuary in northern Tamil Nadu, housing three rock-cut cave temples, an active structural temple, medieval Chola murals, and a celebrated 16-foot monolithic rock-relief idol of Lord Neminatha (the tallest Jain sculpture in Tamil Nadu). Detailed in Chapter 13 of Dr. Kailash Chand Jain''s treatise.',
    'Inhabited by Digambar ascetics from the early centuries CE. Chola queen Kundavai (sister of Rajaraja Chola I) and Sambuvaraya chieftains granted substantial endowments between the 10th and 14th centuries, recorded in numerous Tamil inscriptions on the cliff faces.',
    'Foremost active Digambar Jain archaeological sanctuary in Tamil Nadu.',
    'Bhagwan Neminatha Monolith, in contemplative Khadgasana (Standing) posture, measuring approximately 16 feet (4.87 meters), sculpted from Granite Cliff Relief, dating to the 10th–11th Century CE, (Standing in Kayotsarga with conch symbol and celestial fly-whisk attendants.).',
    '{"morning":"07:00 - 12:30 PM (Morning Abhishek, Pakhsal & Jin Puja)","evening":"05:00 PM - 18:00 (Sandhya Darshan & Deep Aradhana)","notes":"Temple opens early for morning pakhsal; visitors are requested to wear traditional clean clothes."}'::jsonb,
